import { icon, money, badge, pageHeading, statCard, escapeHTML } from './ui.js';
import { evaluateRemote, calculate } from './engine.js';

const e = value => escapeHTML(String(value ?? ''));
const today = '2026-10-23';
const ui = { evaluationId: '', evaluationMode: 'applicant', result: null, resultId: '', resultInputs: null };
const products = [
  ['Regular loan', 'Everyday needs', 36, 'wallet'], ['Economic loan', 'Financial flexibility', 24, 'chart'],
  ['Short-term loan', 'Immediate expenses', 6, 'clock'], ['SEMCO loan', 'Member assistance', 24, 'bank'],
  ['Motorcycle loan', 'Personal transport', 36, 'briefcase'], ['Appliance / Special loan', 'Home essentials', 24, 'grid'],
  ['Medical loan', 'Health and emergencies', 24, 'activity'], ['Credit card loan', 'Balance consolidation', 24, 'receipt'],
  ['Laptop loan', 'Work and education', 24, 'document'], ['Property / Vehicle loan', 'Major purchases', 60, 'bank'],
];
const button = (label, attrs = '', type = 'light', glyph = '') => `<button type="button" class="btn btn-${type}" ${attrs}>${glyph ? icon(glyph) : ''}${label}</button>`;
const nav = (label, view, type = 'light', glyph = '') => button(label, `data-nav="${e(view)}"`, type, glyph);
const panel = (title, body, action = '', subtitle = '') => `<section class="panel">${title || action || subtitle ? `<div class="panel-head"><div>${title ? `<h2 class="section-title">${title}</h2>` : ''}${subtitle ? `<p class="muted text-small mb-0 mt-1">${subtitle}</p>` : ''}</div>${action}</div>` : ''}${body}</section>`;
const empty = (title, detail = '') => `<div class="empty-state">${icon('check-circle')}<h3>${title}</h3>${detail ? `<p class="muted mb-0">${detail}</p>` : ''}</div>`;
const dateText = value => {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? e(value) : d.toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });
};
const initials = name => String(name || 'Member').trim().split(/\s+/).map(p => p[0]).slice(0, 2).join('');
const memberCell = (name, id, init = '') => `<div class="d-flex align-items-center gap-3"><span class="avatar avatar-sm">${e(init || initials(name))}</span><div><span class="fw-semibold">${e(name)}</span><span class="d-block muted text-small">${e(id)}</span></div></div>`;
const filters = (placeholder, extra = '', id = 'record-search') => `<div class="filter-row"><div class="search-field flex-grow-1 position-relative"><span class="position-absolute top-50 start-0 translate-middle-y ms-3 muted">${icon('search')}</span><input id="${id}" class="form-control ps-5" type="search" placeholder="${e(placeholder)}" aria-label="${e(placeholder)}"></div>${extra}</div>`;
const table = (heads, rows, id = '', emptyCols = heads.length) => `<div class="table-responsive"><table class="data-table" ${id ? `id="${id}"` : ''}><thead><tr>${heads.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows || `<tr><td colspan="${emptyCols}" class="text-center muted py-5">No records to display.</td></tr>`}</tbody></table></div>`;
const appStatus = a => a.status || 'Pending';
const pending = state => state.applications.filter(a => ['Pending', 'Verified', 'Evaluated', 'Needs revision'].includes(appStatus(a)));
const field = (label, id, input, note = '') => `<div class="field"><label class="form-label" for="${id}">${label}</label>${input}${note ? `<div class="form-text">${note}</div>` : ''}</div>`;
const numberField = (label, id, value, opts = '') => field(label, id, `<div class="input-group"><span class="input-group-text">₱</span><input type="number" class="form-control" id="${id}" name="${id}" value="${e(value)}" ${/min=/.test(opts) ? '' : 'min="0"'} step="0.01" ${opts} required></div>`);
const sum = values => values.reduce((total, value) => total + Number(value || 0), 0);

function appRows(apps, compact = false) {
  return apps.map(a => `<tr data-record="${e(`${a.id} ${a.memberName} ${a.memberId} ${a.product}`.toLowerCase())}" data-status="${e(appStatus(a))}"><td>${memberCell(a.memberName, a.id, a.initials)}</td><td>${e(a.product)}${compact ? '' : `<span class="d-block muted text-small">${e(a.term)} months</span>`}</td><td class="fw-semibold">${money(a.amount)}</td>${compact ? '' : `<td>${dateText(a.date)}</td>`}<td>${badge(appStatus(a))}</td><td class="text-end">${button('Review', `data-application="${e(a.id)}"`, 'light', 'arrow-up-right')}</td></tr>`).join('');
}

function staffOverview(ctx) {
  const s = ctx.state;
  const queue = pending(s);
  const unverified = s.members.filter(m => !['Active', 'Verified'].includes(m.status));
  return pageHeading('STAFF WORKSPACE', 'A good day to make progress.', 'Here’s what needs your attention across the cooperative.', nav('Review applications', 'applications', 'primary', 'arrow-right')) +
    `<div class="stat-grid">${statCard('Applications to review', queue.length, 'document', 'Across the processing queue')}${statCard('Awaiting verification', s.applications.filter(a => !a.verified && a.status === 'Pending').length, 'shield', 'Complete checks before evaluation')}${statCard('Ready for final review', s.applications.filter(a => a.status === 'Evaluated').length, 'check-circle', 'Chairman / Vice Chairman decision')}${statCard('Payments recorded', money(sum(s.transactions.map(t => t.amount))), 'wallet', `${s.transactions.length} posted demo transactions`)}</div>` +
    `<div class="content-grid"><div>${panel('Application queue', table(['Member / Application', 'Loan facility', 'Amount', 'Status', ''], appRows(queue.slice(0, 5), true)), nav('View all', 'applications', 'light', 'arrow-right'), 'Pick up where your team left off.')}
    ${panel('A clear path from application to decision', `<div class="panel-body"><div class="row g-3">${[['01', 'Verify details', 'Check member records and supporting documents.', 'verification'], ['02', 'Run evaluation', 'Review the SCEA score and belief-based advice.', 'evaluation'], ['03', 'Final decision', 'Route to an authorized officer for final review.', 'applications']].map(([n, title, text, v]) => `<div class="col-md-4"><div class="border rounded-3 p-3 h-100"><span class="eyebrow">STEP ${n}</span><h3 class="h6 mt-3">${title}</h3><p class="muted text-small">${text}</p><button class="btn btn-light btn-sm" data-nav="${v}">Open ${icon('arrow-right')}</button></div></div>`).join('')}</div></div>`)}</div>
    <aside>${panel('Member verification', `<div class="panel-body"><div class="d-flex align-items-center gap-3 mb-3"><span class="stat-icon">${icon('users')}</span><div><strong class="h4 mb-0">${unverified.length}</strong><p class="muted text-small mb-0">accounts need your review</p></div></div><p class="muted text-small">Check an account against the member’s submitted information, then confirm or flag a discrepancy.</p>${nav('Open verification', 'verification', 'outline-secondary', 'shield')}</div>`)}
    ${panel('Today at SEMCO', `<div class="panel-body"><div class="metric-row"><span class="muted">Business date</span><strong>23 October 2026</strong></div><div class="metric-row"><span class="muted">Staff on duty</span><strong>Sofia Reyes</strong></div><div class="metric-row"><span class="muted">Workspace</span><span class="pill blue">Prototype</span></div><div class="info-banner mt-3">${icon('help')}<span>All members and financial records shown here are fictional.</span></div></div>`)}</aside></div>`;
}

function staffApplications(ctx) {
  return pageHeading('LOAN PROCESSING', 'Applications', 'Verify details, review the recommendation, and route each application for a final decision.', nav('Open credit evaluation', 'evaluation', 'primary', 'chart')) +
    panel('All applications', filters('Search member, application ID, or facility', `<select id="application-status" class="form-select" aria-label="Filter by application status"><option value="">All statuses</option>${['Pending', 'Verified', 'Evaluated', 'Approved', 'Rejected', 'Needs revision'].map(s => `<option>${s}</option>`).join('')}</select>`) + table(['Member / Application', 'Loan facility', 'Requested amount', 'Submitted', 'Status', ''], appRows(ctx.state.applications), 'application-table'));
}

function staffVerification(ctx) {
  return pageHeading('MEMBER MANAGEMENT', 'Account verification', 'Review submitted records and flag discrepancies before proceeding with a loan.') +
    `<div class="info-banner mb-4">${icon('shield')}<span>Each member keeps one unique ID. Name changes and corrections stay linked to the same record.</span></div>` +
    panel('Member records', filters('Search name, member ID, or department') + table(['Member', 'Department', 'Email', 'Account status', ''], ctx.state.members.map(m => `<tr data-record="${e(`${m.name} ${m.id} ${m.department} ${m.email}`.toLowerCase())}"><td>${memberCell(m.name, m.id, m.initials)}</td><td>${e(m.department)}</td><td>${e(m.email)}</td><td>${badge(m.status)}</td><td class="text-end">${button('Review record', `data-verify-member="${e(m.id)}"`, 'light', 'eye')}</td></tr>`).join(''), 'verification-table'));
}

function evaluationResult(result, application) {
  if (!result) return `<div class="empty-state py-5">${icon('chart')}<h3>Your evaluation starts here</h3><p class="muted">Review the inputs and run the simple SCEA model to see a score, belief degrees, and the rules behind the recommendation.</p><span class="pill blue">Decision support · illustrative rules</span></div>`;
  const beliefs = result.beliefs || result.beliefDegrees || {};
  const beliefList = Array.isArray(beliefs) ? beliefs.map(b => [b.label || b.outcome, b.value ?? b.degree]) : Object.entries(beliefs);
  const rules = result.rules || result.topRules || [];
  const metrics = result.metrics || {};
  const score = Number(result.score || 0);
  const beliefLabels = { recommended: 'Recommended', review: 'Needs review', notRecommended: 'Not recommended' };
  const metricLabels = { monthlyPayment: 'Estimated monthly payment', dti: 'Debt-to-income ratio', coverage: 'Savings coverage', repayment: 'On-time repayment', comakerDti: 'Co-maker debt-to-income ratio' };
  return `<div class="panel-body"><div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><span class="eyebrow">SCEA CREDIT SCORE</span><div class="result-score">${e(Math.round(score))}<span class="muted fs-5"> / 100</span></div>${badge(result.recommendation || result.outcome || 'Needs Review')}</div><span class="stat-icon">${icon('chart')}</span></div><p class="muted text-small">${e(result.explanation || 'The score combines illustrative affordability, savings, repayment, and co-maker rules. Final approval stays with an authorized officer.')}</p>
    <h3 class="h6 mt-4 mb-3">Belief distribution</h3>${beliefList.map(([label, degree]) => { const n = Number(degree || 0); const pct = Math.max(0, Math.min(100, n <= 1 ? n * 100 : n)); return `<div class="mb-3"><div class="d-flex justify-content-between text-small mb-2"><span>${e(beliefLabels[label] || label.replace(/_/g, ' '))}</span><strong>${pct.toFixed(1)}%</strong></div><div class="progress" style="height:7px"><div class="progress-bar" style="width:${pct}%;${/not|low/i.test(label) ? 'background:#c36a58' : /review|medium/i.test(label) ? 'background:#c59c58' : ''}"></div></div></div>`; }).join('')}
    ${Object.keys(metrics).length ? `<div class="border rounded-3 p-3 my-4">${Object.entries(metrics).filter(([k, v]) => typeof v === 'number').map(([k, v]) => `<div class="metric-row text-small"><span class="muted">${e(metricLabels[k] || k)}</span><strong>${k === 'monthlyPayment' ? money(v) : `${(Number(v) * (k === 'repayment' ? 1 : 100)).toFixed(1)}%`}</strong></div>`).join('')}</div>` : ''}
    <h3 class="h6 mt-4">Why this recommendation?</h3>${rules.length ? rules.slice(0, 4).map((rule, index) => `<div class="rule-row border-bottom py-3"><div class="d-flex justify-content-between text-small mb-1"><strong>Rule ${e(rule.id || index + 1)}</strong>${rule.activation !== undefined || rule.weight !== undefined ? `<span class="muted">${Math.round(Number(rule.activation ?? rule.weight) * 100)}% activation</span>` : ''}</div><p class="text-small muted mb-0">${e(typeof rule === 'string' ? rule : rule.description || rule.rule || rule.text || rule.label || 'Matched financial conditions contribute to the recommendation.')}</p></div>`).join('') : `<p class="muted text-small">Affordable obligations, stronger savings, and consistent repayment increase the recommendation score.</p>`}
    <div class="info-banner mt-4">${icon('help')}<span>Illustrative BRB with weighted rule blending. This is a prototype recommendation, not an official SEMCO credit policy.</span></div>${application ? `<button class="btn btn-primary w-100 mt-3" type="button" id="save-evaluation">${icon('check')}Save recommendation</button>` : ''}</div>`;
}

function staffEvaluation(ctx) {
  const eligible = ctx.state.applications.filter(a => a.verified && !['Rejected', 'Approved'].includes(a.status));
  let app = eligible.find(a => a.id === ui.evaluationId) || eligible[0];
  if (app) ui.evaluationId = app.id;
  const savedResult = ui.evaluationMode === 'comaker' ? app?.comakerEvaluation : app?.evaluation;
  const result = app && ui.resultId === app.id ? ui.result : savedResult;
  return pageHeading('DECISION SUPPORT', 'Credit evaluation', 'A simple, explainable recommendation to support your review. The final decision stays with the Chairman.') +
    (!app ? panel('Verify an application first', empty('No verified applications yet', 'Complete application verification before running the credit evaluation.') + `<div class="text-center pb-4">${nav('Review applications', 'applications', 'primary', 'arrow-right')}</div>`) : `<div class="row g-4"><div class="col-xl-7">${panel('Evaluation inputs', `<form id="evaluation-form" class="panel-body"><div class="row g-3"><div class="col-12">${field('Application', 'evaluation-application', `<select id="evaluation-application" class="form-select">${eligible.map(a => `<option value="${e(a.id)}" ${a.id === app.id ? 'selected' : ''}>${e(a.memberName)} · ${e(a.id)} · ${money(a.amount)}</option>`).join('')}</select>`)}</div><div class="col-12">${field('Evaluate as', 'evaluation-mode', `<select id="evaluation-mode" name="mode" class="form-select"><option value="applicant" ${ui.evaluationMode === 'applicant' ? 'selected' : ''}>Loan applicant</option><option value="comaker" ${ui.evaluationMode === 'comaker' ? 'selected' : ''}>Co-maker</option></select>`, 'Co-maker mode tests the capacity to support this application.')}</div></div><hr class="my-4"><h3 class="h6 mb-3">${ui.evaluationMode === 'comaker' ? 'Co-maker financial details' : 'Applicant financial details'}</h3><div class="row g-3"><div class="col-sm-6">${numberField('Monthly income', 'income', ui.evaluationMode === 'comaker' ? app.comakerIncome ?? 48000 : app.income, 'min="1"')}</div><div class="col-sm-6">${numberField('Monthly active liabilities', 'liabilities', ui.evaluationMode === 'comaker' ? app.comakerLiabilities ?? 5000 : app.liabilities)}</div><div class="col-sm-6">${numberField('Cooperative savings', 'savings', app.savings ?? 25000)}</div><div class="col-sm-6">${field('On-time repayment history', 'repayment', `<div class="input-group"><input type="number" name="repayment" id="repayment" class="form-control" min="0" max="100" step="1" value="${e(app.repayment ?? 95)}" required><span class="input-group-text">%</span></div>`)}</div><div class="col-sm-6">${numberField('Requested loan amount', 'amount', app.amount, 'min="1" readonly')}</div><div class="col-sm-6">${field('Repayment term', 'term', `<div class="input-group"><input type="number" class="form-control" id="term" name="term" value="${e(app.term)}" min="1" max="120" readonly required><span class="input-group-text">months</span></div>`)}</div></div><hr class="my-4"><h3 class="h6 mb-3">${ui.evaluationMode === 'comaker' ? 'Applicant reference' : 'Co-maker capacity'}</h3><div class="row g-3"><div class="col-sm-6">${numberField('Monthly income', 'comakerIncome', ui.evaluationMode === 'comaker' ? app.income : app.comakerIncome ?? 48000, 'min="1"')}</div><div class="col-sm-6">${numberField('Monthly active liabilities', 'comakerLiabilities', ui.evaluationMode === 'comaker' ? app.liabilities : app.comakerLiabilities ?? 5000)}</div></div><div class="info-banner mt-4">${icon('percent')}<span>Using sample rates: ${e(ctx.state.config.annualRate)}% annual interest, ${e(ctx.state.config.serviceRate)}% service fee. BRB affordability anchors: 20% / 40% / 60% (prototype fixed).</span></div><button type="submit" class="btn btn-primary mt-4" id="run-evaluation">${icon('chart')}Run credit evaluation</button></form>`)}
    ${panel('How this prototype works', `<div class="panel-body"><div class="row g-3">${[['1', 'Match inputs', 'Map affordability, savings, repayment and co-maker capacity to low, medium or high.'], ['2', 'Activate rules', 'Apply a small set of transparent IF–THEN belief rules.'], ['3', 'Combine beliefs', 'Blend rule outputs into a score and recommendation.']].map(([n, title, body]) => `<div class="col-md-4"><span class="pill blue">${n}</span><h3 class="h6 mt-3">${title}</h3><p class="muted text-small mb-0">${body}</p></div>`).join('')}</div></div>`)}</div><div class="col-xl-5">${panel('Evaluation result', evaluationResult(result, app), result ? '<span class="pill blue">BRB model</span>' : '')}</div></div>`);
}

function staffMembers(ctx) {
  return pageHeading('CENTRALIZED RECORDS', 'Member directory', 'A single view of member information, applications, and cooperative activity.') + panel('All members', filters('Search name, member ID, email, or department') + table(['Member', 'Department', 'Savings', 'Account status', ''], ctx.state.members.map(m => `<tr data-record="${e(`${m.name} ${m.id} ${m.email} ${m.department}`.toLowerCase())}"><td>${memberCell(m.name, m.id, m.initials)}</td><td>${e(m.department)}</td><td class="fw-semibold">${money(m.savings)}</td><td>${badge(m.status)}</td><td class="text-end">${button('View member', `data-member="${e(m.id)}"`, 'light', 'arrow-up-right')}</td></tr>`).join(''), 'members-table'));
}

function staffLedger(ctx) {
  const t = ctx.state.transactions;
  return pageHeading('PAYMENTS & LEDGER', 'Payment records', 'Record salary deductions and over-the-counter payments in one place.', button('Post a payment', 'id="new-payment"', 'primary', 'plus')) +
    `<div class="stat-grid">${statCard('Total collected', money(sum(t.map(x => x.amount))), 'wallet', 'All posted demo transactions')}${statCard('Salary deductions', money(sum(t.filter(x => /salary/i.test(x.method)).map(x => x.amount))), 'briefcase', 'Recorded through payroll')}${statCard('Over the counter', money(sum(t.filter(x => !/salary/i.test(x.method)).map(x => x.amount))), 'receipt', 'Recorded by cooperative staff')}${statCard('Posted transactions', t.length, 'check-circle', 'Payment history stays linked to a loan')}</div>` +
    panel('Transaction ledger', filters('Search member, transaction, or loan ID', `<select id="payment-method-filter" class="form-select" aria-label="Filter payment method"><option value="">All payment methods</option><option>Salary deduction</option><option>Over the counter</option></select>`) + table(['Transaction / Date', 'Member', 'Loan ID', 'Payment method', 'Amount', 'Status'], [...t].reverse().map(x => `<tr data-record="${e(`${x.id} ${x.memberName} ${x.memberId} ${x.loanId}`.toLowerCase())}" data-method="${e(x.method)}"><td><strong>${e(x.id)}</strong><span class="d-block text-small muted">${dateText(x.date)}</span></td><td>${e(x.memberName)}</td><td>${e(x.loanId)}</td><td>${e(x.method)}</td><td class="fw-semibold">${money(x.amount)}</td><td>${badge(x.status || 'Posted')}</td></tr>`).join(''), 'ledger-table')) + `<div class="info-banner mt-4">${icon('help')}<span>Members view payments in their portal. Payments are collected through salary deduction or over the counter; there is no online payment gateway. Demo payments reduce principal directly; interest allocation is illustrative.</span></div>`;
}

function reports(ctx, admin = false) {
  const reportTypes = admin ? [['Monthly cooperative summary', 'Applications, decisions, and collections in one overview.', 'chart'], ['User activity report', 'A summary of demo users, roles, and account status.', 'users'], ['Audit activity report', 'A review of changes made in this prototype session.', 'history']] : [['Monthly collection report', 'Salary deductions and over-the-counter collections.', 'chart'], ['Member statement of account', 'A consolidated view of member loans and payments.', 'document'], ['Payment voucher', 'A sample voucher for a recorded cooperative payment.', 'receipt'], ['Loan payment schedule', 'A preview of estimated monthly loan installments.', 'calendar']];
  return pageHeading('REPORTS & DOCUMENTS', 'Every record, a clearer picture.', 'Explore the report layouts that will support cooperative record keeping.') + `<div class="row g-4">${reportTypes.map(([title, description, glyph]) => `<div class="col-md-6">${panel('', `<div class="panel-body"><span class="stat-icon mb-4">${icon(glyph)}</span><h2 class="h5">${title}</h2><p class="muted">${description}</p><button class="btn btn-outline-secondary mt-2" data-report="${e(title)}">${icon('eye')}Preview report</button></div>`)}</div>`).join('')}</div><div class="info-banner mt-4">${icon('document')}<span>Document previews show the intended layout. PDF generation and printing are outside this frontend prototype.</span></div>`;
}

function adminOverview(ctx) {
  const s = ctx.state;
  return pageHeading('ADMINISTRATOR WORKSPACE', 'A well-run cooperative starts here.', 'Manage the people, policies, and records behind your member experience.', nav('System configuration', 'configuration', 'primary', 'settings')) +
    `<div class="stat-grid">${statCard('Registered members', s.members.length, 'users', 'Unique, centralized member records')}${statCard('Demo user accounts', s.users.length, 'shield', 'Member, staff, and administrator roles')}${statCard('Loan facilities', '10', 'bank', 'Serving different member needs')}${statCard('Audit events', s.audit.length, 'history', 'Actions recorded in this browser')}</div>` +
    `<div class="content-grid"><div>${panel('Recent system activity', auditTable(s.audit.slice(0, 6)), nav('View audit log', 'audit', 'light', 'arrow-right'), 'An overview of the latest recorded actions.')}${panel('Administration essentials', `<div class="panel-body"><div class="row g-3">${[['users', 'Manage users', 'Review role assignments and demo account status.', 'users'], ['percent', 'Loan policies', 'Adjust the sample rates used by the calculator.', 'configuration'], ['bank', 'Loan facilities', 'Explore all ten facilities offered to members.', 'products']].map(([glyph, title, body, v]) => `<div class="col-md-4"><span class="stat-icon mb-3">${icon(glyph)}</span><h3 class="h6">${title}</h3><p class="muted text-small">${body}</p>${nav('Manage', v, 'light', 'arrow-right')}</div>`).join('')}</div></div>`)}</div><aside>${panel('Workspace status', `<div class="panel-body"><div class="d-flex gap-3 align-items-center mb-4"><span class="stat-icon">${icon('check-circle')}</span><div><strong>Prototype is ready</strong><p class="muted text-small mb-0">Local demo workspace</p></div></div><div class="metric-row"><span class="muted">Annual sample rate</span><strong>${e(s.config.annualRate)}%</strong></div><div class="metric-row"><span class="muted">Service fee</span><strong>${e(s.config.serviceRate)}%</strong></div><div class="metric-row"><span class="muted">BRB anchors (fixed)</span><strong>20% / 40% / 60%</strong></div><div class="metric-row"><span class="muted">Maintenance flag</span><span class="pill blue">${s.config.maintenance ? 'Enabled (demo)' : 'Off'}</span></div><div class="info-banner mt-4">${icon('help')}<span>All records are fictional. Role switching and account controls demonstrate the intended flow.</span></div></div>`)}${panel('Designed for your team', `<div class="panel-body"><p class="muted text-small">Member self-service, staff processing, and administrator controls each have their own workspace.</p>${nav('View user accounts', 'users', 'outline-secondary', 'users')}</div>`)}</aside></div>`;
}

function adminUsers(ctx) {
  return pageHeading('ACCESS MANAGEMENT', 'User accounts', 'Explore how roles and account status organize access to the cooperative.', button('Add demo account', 'id="add-user"', 'primary', 'plus')) +
    `<div class="info-banner mb-4">${icon('shield')}<span>These controls update fictional accounts only. The prototype does not implement production authentication or access enforcement.</span></div>` + panel('All accounts', filters('Search name, account ID, email, or role') + table(['User', 'Email', 'Role', 'Status', ''], ctx.state.users.map(u => `<tr data-record="${e(`${u.name} ${u.id} ${u.email} ${u.role}`.toLowerCase())}"><td>${memberCell(u.name, u.id)}</td><td>${e(u.email)}</td><td><select class="form-select form-select-sm" style="min-width:120px" aria-label="Role for ${e(u.name)}" data-user-role="${e(u.id)}">${['member', 'staff', 'admin'].map(role => `<option value="${role}" ${String(u.role).toLowerCase() === role ? 'selected' : ''}>${role[0].toUpperCase() + role.slice(1)}</option>`).join('')}</select></td><td>${badge(u.status)}</td><td class="text-end">${button(u.status === 'Active' ? 'Deactivate' : 'Activate', `data-user-status="${e(u.id)}"`, 'light')}</td></tr>`).join(''), 'users-table'));
}

function adminProducts(ctx) {
  return pageHeading('LOAN MANAGEMENT', 'Loan facilities', 'Ten ways to help members move forward. Browse the sample product setup.', nav('Edit sample policies', 'configuration', 'primary', 'settings')) + `<div class="info-banner mb-4">${icon('help')}<span>Rates and term limits below are illustrative prototype values. Official facility policies were not provided in the research.</span></div><div class="row g-4">${products.map(([name, desc, term, glyph], index) => `<div class="col-md-6 col-xl-4">${panel('', `<div class="panel-body"><div class="d-flex justify-content-between mb-4"><span class="stat-icon">${icon(glyph)}</span><span class="pill green">Available</span></div><h2 class="h5">${name}</h2><p class="muted text-small">${desc}</p><div class="metric-row mt-4"><span class="muted text-small">Annual sample rate</span><strong>${e(ctx.state.config.annualRate)}%</strong></div><div class="metric-row"><span class="muted text-small">Sample maximum term</span><strong>${term} months</strong></div><button type="button" class="btn btn-light mt-3" data-product="${index}">View facility ${icon('arrow-right')}</button></div>`)}</div>`).join('')}</div>`;
}

function adminConfiguration(ctx) {
  const c = ctx.state.config;
  return pageHeading('SYSTEM MAINTENANCE', 'Configuration', 'Set the sample values used by the loan calculator and credit evaluation.') + `<form id="configuration-form"><div class="content-grid"><div>${panel('Loan calculation settings', `<div class="panel-body"><div class="row g-4"><div class="col-md-6">${field('Annual interest rate', 'annualRate', `<div class="input-group"><input name="annualRate" id="annualRate" class="form-control" type="number" min="0" max="50" step="0.1" value="${e(c.annualRate)}" required><span class="input-group-text">%</span></div>`, 'Sample annual rate used in new calculations.')}</div><div class="col-md-6">${field('Service fee', 'serviceRate', `<div class="input-group"><input name="serviceRate" id="serviceRate" class="form-control" type="number" min="0" max="20" step="0.1" value="${e(c.serviceRate)}" required><span class="input-group-text">%</span></div>`, 'Deducted from the estimated loan proceeds.')}</div></div><div class="info-banner mt-4">${icon('percent')}<span>The calculator uses these values for new estimates. Existing evaluations retain their saved recommendation.</span></div></div>`)}${panel('Credit evaluation settings', `<div class="panel-body"><div class="row g-4"><div class="col-md-6"><div class="border rounded-3 p-3 h-100"><span class="eyebrow">ILLUSTRATIVE RULE BASE</span><p class="fw-semibold mb-1 mt-2">BRB affordability anchors: 20% / 40% / 60% (prototype fixed)</p><p class="muted text-small mb-0">Fixed reference levels keep the simple evaluation model transparent.</p></div></div><div class="col-md-6"><div class="border rounded-3 p-3 h-100"><span class="eyebrow">DECISION AUTHORITY</span><p class="fw-semibold mb-1 mt-2">Chairman / Vice Chairman</p><p class="muted text-small mb-0">The recommendation supports review and never approves a loan automatically.</p></div></div></div></div>`)}</div><aside>${panel('Workspace options', `<div class="panel-body"><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" role="switch" name="maintenance" id="maintenance" ${c.maintenance ? 'checked' : ''}><label class="form-check-label fw-semibold" for="maintenance">Maintenance flag</label></div><p class="muted text-small">Shows how an administrator could signal planned maintenance. The prototype remains accessible.</p><hr class="my-4"><span class="eyebrow">PROTOTYPE SETTINGS</span><p class="muted text-small mt-2">Values are sample policies for demonstrating the research workflow and are saved locally in this browser.</p><button type="submit" class="btn btn-primary w-100 mt-3">${icon('check')}Save configuration</button></div>`)}</aside></div></form>`;
}

function auditTable(events, id = '') {
  return table(['Event / Time', 'Performed by', 'Action', 'Details'], events.map(x => `<tr data-record="${e(`${x.id} ${x.actor} ${x.action} ${x.details}`.toLowerCase())}" data-date="${e(String(x.date).slice(0, 10))}"><td><strong class="text-small">${e(x.id)}</strong><span class="d-block muted text-small">${dateText(x.date)}</span></td><td>${e(x.actor)}</td><td><span class="fw-semibold text-small">${e(x.action)}</span></td><td class="muted text-small">${e(x.details)}</td></tr>`).join(''), id);
}

function adminAudit(ctx) {
  return pageHeading('SYSTEM ACTIVITY', 'Audit log', 'Follow a clear trail of demo account, application, payment, and policy changes.') + panel('Recorded events', filters('Search actor, action, event ID, or details', `<div class="d-flex align-items-center gap-2"><label class="text-small muted" for="audit-from">From</label><input type="date" class="form-control" id="audit-from" aria-label="Audit start date"><label class="text-small muted" for="audit-to">To</label><input type="date" class="form-control" id="audit-to" aria-label="Audit end date"></div>`) + auditTable(ctx.state.audit, 'audit-table')) + `<p class="muted text-small mt-3">This prototype stores a local activity trail for demonstration; it is not a production immutable audit service.</p>`;
}

export function renderStaff(view, ctx) {
  return ({ overview: staffOverview, applications: staffApplications, verification: staffVerification, evaluation: staffEvaluation, members: staffMembers, ledger: staffLedger, reports: c => reports(c) }[view] || staffOverview)(ctx);
}

export function renderAdmin(view, ctx) {
  return ({ overview: adminOverview, users: adminUsers, products: adminProducts, configuration: adminConfiguration, audit: adminAudit, reports: c => reports(c, true) }[view] || adminOverview)(ctx);
}

function persist(ctx, action, details, message) {
  ctx.addAudit(action, details);
  ctx.save();
  ctx.closeModal();
  ctx.render();
  if (message) ctx.toast(message);
}

function applicationModal(id, ctx) {
  const a = ctx.state.applications.find(x => x.id === id);
  if (!a) return;
  const steps = ['Submitted', 'Verified', 'Evaluated', 'Final decision'];
  const stage = a.status === 'Pending' || a.status === 'Needs revision' ? 0 : a.status === 'Verified' ? 1 : a.status === 'Evaluated' ? 2 : 3;
  const body = `<div class="d-flex justify-content-between align-items-center gap-3 mb-4">${memberCell(a.memberName, a.memberId, a.initials)}${badge(a.status)}</div><div class="row g-2 mb-4">${steps.map((step, i) => `<div class="col-3"><div class="border-top border-3 pt-2 ${i <= stage ? 'border-success' : ''}"><span class="text-small ${i <= stage ? 'fw-semibold' : 'muted'}">${i + 1}. ${step}</span></div></div>`).join('')}</div><div class="row g-4"><div class="col-sm-6"><span class="muted text-small">Loan facility</span><p class="fw-semibold mb-0">${e(a.product)}</p></div><div class="col-sm-6"><span class="muted text-small">Requested amount</span><p class="fw-semibold mb-0">${money(a.amount)}</p></div><div class="col-sm-6"><span class="muted text-small">Repayment term</span><p class="fw-semibold mb-0">${e(a.term)} months</p></div><div class="col-sm-6"><span class="muted text-small">Submitted on</span><p class="fw-semibold mb-0">${dateText(a.date)}</p></div><div class="col-sm-6"><span class="muted text-small">Monthly income</span><p class="fw-semibold mb-0">${money(a.income)}</p></div><div class="col-sm-6"><span class="muted text-small">Monthly liabilities</span><p class="fw-semibold mb-0">${money(a.liabilities)}</p></div></div>${a.evaluation ? `<div class="border rounded-3 p-3 mt-4"><span class="eyebrow">SAVED CREDIT RECOMMENDATION</span><div class="d-flex align-items-center justify-content-between mt-2"><strong>Score ${e(Math.round(a.evaluation.score || 0))} / 100</strong>${badge(a.evaluation.recommendation || 'Needs Review')}</div></div>` : ''}${a.decisionReason ? `<div class="info-banner mt-4">${icon('document')}<span>${e(a.reviewer || 'Authorized officer')} · ${e(a.decisionReason)}</span></div>` : ''}<div class="info-banner mt-4">${icon('help')}<span>${a.status === 'Pending' ? 'Verify the submitted details before running the credit evaluation.' : a.status === 'Verified' ? 'The application is verified and ready for an SCEA recommendation.' : a.status === 'Evaluated' ? 'The recommendation is ready. Route this application for a simulated final officer review.' : a.status === 'Needs revision' ? 'The member must correct the flagged information and resubmit.' : 'The final decision has been recorded in this demo.'}</span></div>`;
  let actions = button('Close', 'data-close-modal', 'light');
  if (a.status === 'Pending') actions += button('Verify application', 'id="verify-application"', 'primary', 'shield');
  if (a.status === 'Verified') actions += button('Run evaluation', 'id="evaluate-application"', 'primary', 'chart');
  if (a.status === 'Evaluated') actions += button('Route to final review', 'id="route-decision"', 'primary', 'arrow-right');
  ctx.openModal(`Application ${e(a.id)}`, body, actions);
  document.querySelector('#verify-application')?.addEventListener('click', () => verificationModal(a, ctx));
  document.querySelector('#evaluate-application')?.addEventListener('click', () => { ui.evaluationId = a.id; ui.result = null; ui.resultId = ''; ctx.closeModal(); ctx.navigate('evaluation'); });
  document.querySelector('#route-decision')?.addEventListener('click', () => decisionModal(a, ctx));
}

function verificationModal(a, ctx) {
  const member = ctx.state.members.find(m => m.id === a.memberId);
  if (member && !['Active', 'Verified'].includes(member.status)) {
    ctx.openModal('Verify the member account first', `<div class="info-banner">${icon('shield')}<span>${e(member.name)}’s account is awaiting verification. Review their member record before verifying this loan application.</span></div>`, button('Close', 'data-close-modal', 'light') + button('Review member record', 'id="review-linked-member"', 'primary', 'user'));
    document.querySelector('#review-linked-member')?.addEventListener('click', () => memberModal(member.id, ctx, true));
    return;
  }
  ctx.openModal('Verify application details', `<p class="muted">Review the fictional supporting information for <strong>${e(a.memberName)}</strong>. Complete each check before proceeding.</p><form id="verify-application-form">${[['identity', 'Member identity and unique ID match the record'], ['financial', 'Income and active liabilities have been checked'], ['documents', 'Application and co-maker details are complete']].map(([id, text]) => `<div class="form-check border rounded-3 p-3 ps-5 mb-3"><input class="form-check-input" type="checkbox" id="verify-${id}" required><label class="form-check-label" for="verify-${id}">${text}</label></div>`).join('')}</form>`, button('Flag discrepancy', 'id="application-discrepancy"', 'outline-secondary') + '<button type="submit" form="verify-application-form" class="btn btn-primary">Verify & continue</button>');
  document.querySelector('#verify-application-form')?.addEventListener('submit', event => { event.preventDefault(); a.verified = true; a.status = 'Verified'; persist(ctx, 'Application verified', `${a.id} · ${a.memberName}`, 'Application verified. Ready for credit evaluation.'); });
  document.querySelector('#application-discrepancy')?.addEventListener('click', () => discrepancyModal(a, 'application', ctx));
}

function discrepancyModal(record, kind, ctx) {
  ctx.openModal('Flag a discrepancy', `<form id="discrepancy-form"><p class="muted">Describe the information that needs correction. This note appears on the demo record.</p>${field('Reason for revision', 'discrepancy-reason', '<textarea id="discrepancy-reason" class="form-control" rows="3" minlength="5" required placeholder="For example: monthly income does not match the submitted payslip."></textarea>')}</form>`, button('Cancel', 'data-close-modal', 'light') + '<button class="btn btn-primary" type="submit" form="discrepancy-form">Request correction</button>');
  document.querySelector('#discrepancy-form')?.addEventListener('submit', event => { event.preventDefault(); const reason = document.querySelector('#discrepancy-reason').value.trim(); if (reason.length < 5) return; record.status = 'Needs revision'; record.revisionReason = reason; if (kind === 'application') { record.verified = false; record.evaluation = null; record.comakerEvaluation = null; } persist(ctx, 'Discrepancy flagged', `${record.id} · ${reason}`, 'The record was flagged for correction.'); });
}

function decisionModal(a, ctx) {
  if (!a.verified || !a.evaluation || a.status !== 'Evaluated') { ctx.toast('Verify and evaluate the applicant before routing a final review.'); return; }
  ctx.openModal('Simulated final officer review', `<div class="info-banner mb-4">${icon('shield')}<span>This screen demonstrates routing to the Chairman / Vice Chairman. The staff account does not represent real approval authority.</span></div><form id="decision-form">${field('Final reviewing officer', 'decision-officer', '<select class="form-select" id="decision-officer" required><option>Chairman (demo)</option><option>Vice Chairman (demo)</option></select>')}<div class="mt-3">${field('Final decision', 'decision-status', '<select class="form-select" id="decision-status" required><option value="">Choose a decision</option><option>Approved</option><option>Rejected</option><option>Needs revision</option></select>')}</div><div class="mt-3">${field('Officer’s review note', 'decision-reason', '<textarea class="form-control" id="decision-reason" rows="3" minlength="5" required placeholder="Enter the reason for this simulated decision."></textarea>')}</div>${a.evaluation ? `<p class="muted text-small mt-3 mb-0">SCEA recommendation: ${e(a.evaluation.recommendation)} · ${e(Math.round(a.evaluation.score || 0))}/100. A recommendation never makes this decision automatically.</p>` : ''}</form>`, button('Cancel', 'data-close-modal', 'light') + '<button type="submit" form="decision-form" class="btn btn-primary">Record simulated decision</button>');
  document.querySelector('#decision-form')?.addEventListener('submit', event => {
    event.preventDefault(); const reason = document.querySelector('#decision-reason').value.trim(); if (reason.length < 5) return;
    a.status = document.querySelector('#decision-status').value; a.decisionReason = reason; a.reviewer = document.querySelector('#decision-officer').value; a.decisionBy = a.reviewer;
    if (a.status === 'Needs revision') { a.revisionReason = reason; a.verified = false; a.evaluation = null; a.comakerEvaluation = null; }
    if (a.status === 'Approved' && Array.isArray(ctx.state.loans) && !ctx.state.loans.some(l => l.applicationId === a.id)) {
      const calc = calculate({ amount: a.amount, term: a.term, annualRate: ctx.state.config.annualRate, serviceRate: ctx.state.config.serviceRate, method: a.method || 'fixed' });
      ctx.state.loans.push({ id: `LN-DEMO-${Date.now().toString().slice(-6)}`, applicationId: a.id, memberId: a.memberId, product: a.product, amount: a.amount, balance: a.amount, estimateTotal: calc.total, interest: calc.interest, method: a.method || 'fixed', monthly: calc.monthlyPayment, term: a.term, paidMonths: 0, nextDate: '2026-11-23', status: 'Active', rate: ctx.state.config.annualRate });
    }
    persist(ctx, 'Simulated final decision', `${a.id} · ${a.status} · ${a.reviewer} · ${reason}`, `Simulated decision recorded: ${a.status}.`);
  });
}

function memberModal(id, ctx, verify = false) {
  const m = ctx.state.members.find(x => x.id === id);
  if (!m) return;
  const apps = ctx.state.applications.filter(a => a.memberId === id);
  const transactions = ctx.state.transactions.filter(t => t.memberId === id);
  ctx.openModal(verify ? 'Review member account' : 'Member record', `${memberCell(m.name, m.id, m.initials)}<div class="row g-4 mt-1"><div class="col-sm-6"><span class="muted text-small">Email address</span><p class="fw-semibold mb-0">${e(m.email)}</p></div><div class="col-sm-6"><span class="muted text-small">Department</span><p class="fw-semibold mb-0">${e(m.department)}</p></div><div class="col-sm-6"><span class="muted text-small">Cooperative savings</span><p class="fw-semibold mb-0">${money(m.savings)}</p></div><div class="col-sm-6"><span class="muted text-small">Monthly income</span><p class="fw-semibold mb-0">${money(m.income)}</p></div><div class="col-sm-6"><span class="muted text-small">Account status</span><div class="mt-1">${badge(m.status)}</div></div><div class="col-sm-6"><span class="muted text-small">Loan applications</span><p class="fw-semibold mb-0">${apps.length} applications · ${transactions.length} payments</p></div></div>${m.revisionReason ? `<div class="info-banner mt-4">${icon('help')}<span>${e(m.revisionReason)}</span></div>` : ''}${verify ? `<div class="info-banner mt-4">${icon('document')}<span>Identity, employment and membership documents are represented as sample records in this prototype.</span></div><div class="form-check mt-4"><input class="form-check-input" type="checkbox" id="member-check"><label class="form-check-label" for="member-check">I have reviewed the member’s submitted details.</label></div>` : `<h3 class="h6 mt-4">Loan history</h3>${apps.length ? `<div class="list-group list-group-flush">${apps.map(a => `<div class="list-group-item px-0 d-flex justify-content-between gap-3"><div><strong class="text-small">${e(a.product)}</strong><span class="d-block muted text-small">${e(a.id)} · ${money(a.amount)}</span></div>${badge(a.status)}</div>`).join('')}</div>` : '<p class="muted text-small">No loan applications yet.</p>'}`}`, button('Close', 'data-close-modal', 'light') + (verify ? button('Flag discrepancy', 'id="member-discrepancy"', 'outline-secondary') + button('Confirm verified', 'id="confirm-member" disabled', 'primary', 'check') : ''));
  document.querySelector('#member-check')?.addEventListener('change', event => { document.querySelector('#confirm-member').disabled = !event.target.checked; });
  document.querySelector('#confirm-member')?.addEventListener('click', () => { m.status = 'Verified'; m.revisionReason = ''; persist(ctx, 'Member verified', `${m.id} · ${m.name}`, 'Member account verified.'); });
  document.querySelector('#member-discrepancy')?.addEventListener('click', () => discrepancyModal(m, 'member', ctx));
}

function paymentModal(ctx) {
  const approved = (ctx.state.loans || []).filter(a => a.status === 'Active' && Number(a.balance) > 0).map(a => ({ ...a, memberName: ctx.state.members.find(m => m.id === a.memberId)?.name || 'Demo member' }));
  if (!approved.length) { ctx.openModal('Post a payment', empty('No active loans yet', 'Complete verification, evaluation, and a simulated final approval before posting a loan payment.'), button('Close', 'data-close-modal', 'light')); return; }
  ctx.openModal('Post a payment', `<form id="payment-form"><p class="muted">Record a fictional payment collected through payroll or at the cooperative counter.</p>${field('Member / Loan account', 'payment-loan', `<select class="form-select" id="payment-loan" required>${approved.map(a => `<option value="${e(a.id)}">${e(a.memberName)} · ${e(a.id)} · ${e(a.product)}</option>`).join('')}</select>`)}<div class="row g-3 mt-1"><div class="col-sm-6">${numberField('Payment amount', 'payment-amount', '', 'min="0.01"')}</div><div class="col-sm-6">${field('Payment date', 'payment-date', `<input type="date" class="form-control" id="payment-date" max="${today}" value="${today}" required>`)}</div></div><div class="mt-3">${field('Payment method', 'payment-method', '<select class="form-select" id="payment-method"><option>Salary deduction</option><option>Over the counter</option></select>')}</div><div class="info-banner mt-4">${icon('receipt')}<span>The amount will appear in the member’s payment history and ledger. For this prototype, the full payment reduces principal directly; interest allocation is illustrative.</span></div><p id="payment-error" class="text-danger text-small mt-3 mb-0" role="alert"></p></form>`, button('Cancel', 'data-close-modal', 'light') + '<button type="submit" form="payment-form" class="btn btn-primary">Post demo payment</button>');
  document.querySelector('#payment-form')?.addEventListener('submit', event => {
    event.preventDefault(); const a = approved.find(x => x.id === document.querySelector('#payment-loan').value); const amount = Number(document.querySelector('#payment-amount').value);
    const loan = ctx.state.loans.find(l => l.id === a.id); const balance = Number(loan.balance);
    if (!amount || amount > balance) { document.querySelector('#payment-error').textContent = `Enter an amount between ₱0.01 and ${money(balance)} for this loan.`; return; }
    const transaction = { id: `TXN-${Date.now().toString().slice(-7)}`, loanId: a.id, memberId: a.memberId, memberName: a.memberName, date: document.querySelector('#payment-date').value, amount, method: document.querySelector('#payment-method').value, status: 'Posted' };
    ctx.state.transactions.push(transaction); loan.balance = Math.max(0, Math.round((balance - amount) * 100) / 100); if (loan.balance === 0) loan.status = 'Completed';
    persist(ctx, 'Payment posted', `${transaction.id} · ${a.id} · ${money(amount)} · ${transaction.method}`, 'Demo payment posted. The member’s balance and ledger are updated.');
  });
}

function reportModal(title, ctx) {
  const collected = sum(ctx.state.transactions.map(t => t.amount));
  const approved = ctx.state.applications.filter(a => a.status === 'Approved');
  const userReport = title === 'User activity report';
  const auditReport = title === 'Audit activity report';
  const schedule = title === 'Loan payment schedule';
  const a = approved[0] || ctx.state.applications[0];
  let reportBody;
  if (userReport) reportBody = table(['Role', 'Accounts', 'Active'], ['member', 'staff', 'admin'].map(r => `<tr><td>${e(r)}</td><td>${ctx.state.users.filter(u => String(u.role).toLowerCase() === r).length}</td><td>${ctx.state.users.filter(u => String(u.role).toLowerCase() === r && u.status === 'Active').length}</td></tr>`).join(''));
  else if (auditReport) reportBody = auditTable(ctx.state.audit.slice(0, 6));
  else if (title === 'Payment voucher') {
    const t = ctx.state.transactions.at(-1);
    reportBody = t ? `<div class="row g-4"><div class="col-sm-6"><span class="muted text-small">Voucher reference</span><p class="fw-semibold">VCH-${e(t.id)}</p></div><div class="col-sm-6"><span class="muted text-small">Payment date</span><p class="fw-semibold">${dateText(t.date)}</p></div><div class="col-sm-6"><span class="muted text-small">Received from</span><p class="fw-semibold">${e(t.memberName)}</p></div><div class="col-sm-6"><span class="muted text-small">Member / Loan account</span><p class="fw-semibold">${e(t.memberId)} · ${e(t.loanId)}</p></div></div><div class="border rounded-3 p-4 my-3"><span class="muted text-small">Amount received · ${e(t.method)}</span><p class="h2 mt-2 mb-0">${money(t.amount)}</p></div><div class="row g-4 mt-3"><div class="col-6"><div class="border-top pt-2 muted text-small">Prepared by / Signature</div></div><div class="col-6"><div class="border-top pt-2 muted text-small">Reviewed by / Signature</div></div></div>` : '<p class="muted">Post a demo payment to preview its voucher.</p>';
  } else if (title === 'Member statement of account') {
    const member = ctx.state.members[0];
    const loans = (ctx.state.loans || []).filter(l => l.memberId === member?.id);
    const txns = ctx.state.transactions.filter(t => t.memberId === member?.id);
    reportBody = member ? `<div class="mb-4">${memberCell(member.name, member.id, member.initials)}</div><div class="metric-row"><span class="muted">Cooperative savings</span><strong>${money(member.savings)}</strong></div><div class="metric-row mb-4"><span class="muted">Outstanding loan balance</span><strong>${money(sum(loans.map(l => l.balance)))}</strong></div>` + table(['Loan account', 'Facility', 'Balance'], loans.map(l => `<tr><td>${e(l.id)}</td><td>${e(l.product)}</td><td>${money(l.balance)}</td></tr>`).join('')) + `<h3 class="h6 mt-4">Recent payments</h3>` + table(['Date', 'Loan account', 'Amount'], txns.slice(-4).map(t => `<tr><td>${dateText(t.date)}</td><td>${e(t.loanId)}</td><td>${money(t.amount)}</td></tr>`).join('')) : '<p class="muted">No member records yet.</p>';
  }
  else if (schedule && a) {
    const calc = calculate({ amount: a.amount, term: a.term, annualRate: ctx.state.config.annualRate, serviceRate: ctx.state.config.serviceRate, method: a.method || 'fixed' });
    const monthly = calc.monthlyPayment ?? calc.monthlyAmortization ?? Number(a.amount) / Number(a.term);
    reportBody = `<p class="muted text-small">${e(a.memberName)} · ${e(a.id)} · ${money(a.amount)} over ${e(a.term)} months</p>` + table(['Installment', 'Estimated payment', 'Type'], Array.from({ length: Math.min(6, Number(a.term)) }, (_, i) => `<tr><td>Month ${i + 1}</td><td>${money(monthly)}</td><td>${a.method === 'diminishing' ? 'Diminishing-balance estimate' : 'Fixed-rate estimate'}</td></tr>`).join('')) + `<p class="muted text-small mt-3">First ${Math.min(6, Number(a.term))} installments shown for demonstration.</p>`;
  } else reportBody = `<div class="row g-3 mb-4"><div class="col-4"><span class="muted text-small">Applications</span><p class="h4 mt-2">${ctx.state.applications.length}</p></div><div class="col-4"><span class="muted text-small">Approved loans</span><p class="h4 mt-2">${approved.length}</p></div><div class="col-4"><span class="muted text-small">Total collections</span><p class="h4 mt-2">${money(collected)}</p></div></div>` + table(['Transaction', 'Member', 'Amount'], ctx.state.transactions.slice(-5).map(t => `<tr><td>${e(t.id)}</td><td>${e(t.memberName)}</td><td>${money(t.amount)}</td></tr>`).join(''));
  ctx.openModal('Document preview', `<div class="border rounded-3 p-4"><span class="eyebrow">SENATE EMPLOYEES MULTIPURPOSE COOPERATIVE</span><h2 class="h4 mt-3">${e(title)}</h2><p class="muted text-small">Reporting date: 23 October 2026 · Sample document</p><hr class="my-4">${reportBody}<div class="border-top mt-4 pt-3 muted text-small">Prepared by: ${ctx.state.role === 'admin' ? 'Daniel Cruz · Administrator' : 'Sofia Reyes · Cooperative Staff'}<br>Fictional records · For prototype demonstration only</div></div><div class="info-banner mt-3">${icon('document')}<span>This is an on-screen preview. PDF export and printing are outside the prototype.</span></div>`, button('Close preview', 'data-close-modal', 'primary'));
}

function addUserModal(ctx) {
  ctx.openModal('Add demo account', `<form id="add-user-form"><p class="muted">Create a fictional account to demonstrate user administration.</p>${field('Full name', 'new-user-name', '<input class="form-control" id="new-user-name" maxlength="80" minlength="3" required placeholder="e.g. Andrea Mendoza">')}<div class="mt-3">${field('Email address', 'new-user-email', '<input type="email" class="form-control" id="new-user-email" maxlength="120" required placeholder="andrea@example.com">')}</div><div class="mt-3">${field('Workspace role', 'new-user-role', '<select class="form-select" id="new-user-role"><option value="member">Member</option><option value="staff">Staff</option><option value="admin">Administrator</option></select>')}</div><p class="text-danger text-small mt-3 mb-0" id="new-user-error" role="alert"></p></form>`, button('Cancel', 'data-close-modal', 'light') + '<button class="btn btn-primary" type="submit" form="add-user-form">Add demo account</button>');
  document.querySelector('#add-user-form')?.addEventListener('submit', event => { event.preventDefault(); const name = document.querySelector('#new-user-name').value.trim(); const email = document.querySelector('#new-user-email').value.trim().toLowerCase(); if (ctx.state.users.some(u => u.email.toLowerCase() === email)) { document.querySelector('#new-user-error').textContent = 'An account with that email already exists.'; return; } if (name.length < 3) return; const user = { id: `USR-${Date.now().toString().slice(-6)}`, name, email, role: document.querySelector('#new-user-role').value, status: 'Active' }; ctx.state.users.push(user); persist(ctx, 'Demo user created', `${user.id} · ${name} · ${user.role}`, 'Demo account added.'); });
}

function bindSearch(tableSelector, extra = () => true) {
  const search = document.querySelector('#record-search');
  const filter = () => {
    const query = (search?.value || '').trim().toLowerCase();
    const tbody = document.querySelector(`${tableSelector} tbody`);
    if (!tbody) return;
    const rows = [...tbody.querySelectorAll('tr[data-record]')];
    let shown = 0;
    rows.forEach(row => { const match = row.dataset.record.includes(query) && extra(row); row.hidden = !match; if (match) shown++; });
    let noResults = tbody.querySelector('[data-empty-results]');
    if (rows.length && !shown && !noResults) { noResults = document.createElement('tr'); noResults.dataset.emptyResults = 'true'; const cell = document.createElement('td'); cell.colSpan = document.querySelector(`${tableSelector} thead tr`)?.children.length || 5; cell.className = 'text-center muted py-5'; cell.textContent = 'No matching records. Try a different search or filter.'; noResults.appendChild(cell); tbody.appendChild(noResults); }
    if (noResults) noResults.hidden = shown > 0;
  };
  search?.addEventListener('input', filter);
  return filter;
}

export function bindOperators(role, view, ctx) {
  document.querySelectorAll('[data-application]').forEach(b => b.addEventListener('click', () => applicationModal(b.dataset.application, ctx)));
  document.querySelectorAll('[data-member]').forEach(b => b.addEventListener('click', () => memberModal(b.dataset.member, ctx)));
  document.querySelectorAll('[data-verify-member]').forEach(b => b.addEventListener('click', () => memberModal(b.dataset.verifyMember, ctx, true)));
  document.querySelectorAll('[data-report]').forEach(b => b.addEventListener('click', () => reportModal(b.dataset.report, ctx)));
  document.querySelectorAll('[data-product]').forEach(b => b.addEventListener('click', () => { const [name, desc, term] = products[Number(b.dataset.product)]; ctx.openModal(name, `<p class="muted">${desc}</p><div class="metric-row"><span>Annual sample interest</span><strong>${e(ctx.state.config.annualRate)}%</strong></div><div class="metric-row"><span>Sample service fee</span><strong>${e(ctx.state.config.serviceRate)}%</strong></div><div class="metric-row"><span>Sample maximum term</span><strong>${term} months</strong></div><div class="info-banner mt-4">${icon('help')}<span>These values illustrate the loan facility interface and are not official SEMCO policies. The member portal provides an estimated calculation before submission.</span></div>`, button('Close', 'data-close-modal', 'primary')); }));
  if (view === 'applications') { const filter = bindSearch('#application-table', row => !document.querySelector('#application-status').value || row.dataset.status === document.querySelector('#application-status').value); document.querySelector('#application-status')?.addEventListener('change', filter); }
  if (view === 'verification') bindSearch('#verification-table');
  if (view === 'members') bindSearch('#members-table');
  if (view === 'users') bindSearch('#users-table');
  if (view === 'ledger') { const filter = bindSearch('#ledger-table', row => !document.querySelector('#payment-method-filter').value || row.dataset.method.toLowerCase() === document.querySelector('#payment-method-filter').value.toLowerCase()); document.querySelector('#payment-method-filter')?.addEventListener('change', filter); }
  if (view === 'audit') { const filter = bindSearch('#audit-table', row => { const from = document.querySelector('#audit-from').value; const to = document.querySelector('#audit-to').value; return (!from || row.dataset.date >= from) && (!to || row.dataset.date <= to); }); document.querySelector('#audit-from')?.addEventListener('change', filter); document.querySelector('#audit-to')?.addEventListener('change', filter); }
  document.querySelector('#new-payment')?.addEventListener('click', () => paymentModal(ctx));
  document.querySelector('#add-user')?.addEventListener('click', () => addUserModal(ctx));
  document.querySelectorAll('[data-user-role]').forEach(select => select.addEventListener('change', () => { const u = ctx.state.users.find(x => x.id === select.dataset.userRole); if (!u) return; u.role = select.value; persist(ctx, 'Demo role changed', `${u.id} · ${u.name} → ${u.role}`, 'Demo workspace role updated.'); }));
  document.querySelectorAll('[data-user-status]').forEach(b => b.addEventListener('click', () => { const u = ctx.state.users.find(x => x.id === b.dataset.userStatus); if (!u) return; u.status = u.status === 'Active' ? 'Inactive' : 'Active'; persist(ctx, 'Demo account status changed', `${u.id} · ${u.name} → ${u.status}`, `Demo account ${u.status.toLowerCase()}.`); }));
  document.querySelector('#configuration-form')?.addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); ctx.state.config.annualRate = Number(data.get('annualRate')); ctx.state.config.serviceRate = Number(data.get('serviceRate')); ctx.state.config.maintenance = data.has('maintenance'); persist(ctx, 'Configuration updated', `Annual rate ${ctx.state.config.annualRate}% · Service fee ${ctx.state.config.serviceRate}%`, 'Sample configuration saved.'); });
  document.querySelector('#evaluation-application')?.addEventListener('change', event => { ui.evaluationId = event.target.value; ui.result = null; ui.resultId = ''; ctx.render(); });
  document.querySelector('#evaluation-mode')?.addEventListener('change', event => { ui.evaluationMode = event.target.value; ui.result = null; ui.resultId = ''; ctx.render(); });
  document.querySelector('#evaluation-form')?.addEventListener('submit', async event => {
    event.preventDefault(); const form = event.target; const btn = form.querySelector('[type="submit"]'); const data = Object.fromEntries(new FormData(form)); const a = ctx.state.applications.find(x => x.id === ui.evaluationId); if (!a?.verified) return;
    ['income', 'liabilities', 'savings', 'repayment', 'amount', 'term', 'comakerIncome', 'comakerLiabilities'].forEach(key => { data[key] = Number(data[key]); });
    Object.assign(data, { annualRate: ctx.state.config.annualRate, serviceRate: ctx.state.config.serviceRate, method: a.method || 'fixed', mode: ui.evaluationMode }); btn.disabled = true; btn.textContent = 'Evaluating…';
    try { const result = await evaluateRemote(data); ui.result = result; ui.resultId = a.id; ui.resultInputs = { ...data }; ctx.render(); ctx.toast('Evaluation complete. Review the recommendation before saving.'); }
    catch (error) { btn.disabled = false; btn.innerHTML = `${icon('chart')}Run credit evaluation`; ctx.toast(error.message || 'The evaluation could not be completed. Please try again.'); }
  });
  document.querySelector('#save-evaluation')?.addEventListener('click', () => {
    const a = ctx.state.applications.find(x => x.id === ui.evaluationId);
    const saved = ui.evaluationMode === 'comaker' ? a?.comakerEvaluation : a?.evaluation;
    const result = ui.resultId === a?.id ? ui.result : saved; if (!a || !result) return;
    const snapshot = { ...result, inputs: ui.resultId === a.id ? ui.resultInputs : saved?.inputs, mode: ui.evaluationMode };
    if (ui.evaluationMode === 'comaker') a.comakerEvaluation = snapshot;
    else { a.evaluation = snapshot; a.status = 'Evaluated'; }
    persist(ctx, 'Credit evaluation saved', `${a.id} · ${result.recommendation} · Score ${Math.round(result.score || 0)} · ${ui.evaluationMode}`, ui.evaluationMode === 'comaker' ? 'Co-maker recommendation saved. Complete the applicant evaluation before final review.' : 'Recommendation saved. The application is ready for final officer review.');
  });
}
